    issueDate: invoice.issueDate,
    status: invoice.status,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    lines: newLines,
  };

  if (invoice.voucher) result.voucher = invoice.voucher;

  return ok(result);
