      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 20, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 1000 = 10000, discount 10% = 1000, after discount 9000, VAT 21% = 1890
  // Line 2: 5 * 2000 = 10000, discount 20% = 2000, after discount 8000, VAT 9% = 720
  // subtotal: 20000, discount: 3000, vat: 1890 + 720 = 2610, total: 20000 - 3000 + 2610 = 19610
  assert.deepEqual(totals, { subtotal: 20000, discount: 3000, vat: 2610, total: 19610 });
});

